/*
 * sprite_frame.h: a sprite frame is drawn with one or more hardware sprites
 * (parts), each at most 64 pixels wide. Frames are generated by
 * assets/gen-assets.py into frames.h.
 */

#ifndef SPRITE_FRAME_H
#define SPRITE_FRAME_H

struct sprite_part {
	unsigned short addr;	/* word address of the top left pixel */
	unsigned char w, h;	/* size in pixels */
	short dx, dy;		/* position in the frame */
};

struct sprite_frame {
	unsigned char n;	/* number of parts */
	const struct sprite_part* parts;
	short hx, hy, hw, hh;	/* hit box */
	short w, h;		/* size */
};

#endif
